// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        // Bound timestamps to plausible values
        vm.assume(timestamp > 0 && timestamp < block.timestamp + 1000000);
        // Bound block numbers to avoid overflow
        blockNumber = bound(blockNumber, 1, 2**64 - 1);

        // Ensure the first call will have a valid pastBlockTime
        vm.roll(blockNumber);
        vm.warp(timestamp);

        // Fund the contract with enough ether to receive 10 wei (the required msg.value is 10 ether)
        vm.deal(address(c), 100 ether);

        // Make the first call to set pastBlockTime
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Now make a second call at a different block/time (must be > previous timestamp)
        vm.roll(blockNumber + 1);
        vm.warp(timestamp + 100);

        // Record balance before the call
        uint256 balanceBefore = address(c).balance;

        (bool success2, ) = address(c).call{value: 10 ether}("");

        uint256 balanceAfter = address(c).balance;

        // General rule: If the call succeeded and block.number % 15 == 0, the contract's balance should be zero (transferred out)
        // The modified version triggers on % 10, so for % 15 == 0 but % 10 != 0, the reference transfers all, the mutant does not.
        // This is a difference in behavior.
        assertTrue(success2 && (blockNumber + 1) % 15 == 0 ? balanceAfter == 0 : true);
    }
}

